<script setup lang="ts">
import {ref,onMounted,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api} from '../../shared/api/ApiClient'
import {auth} from '../auth/AuthService'
import {teamService,type Member} from '../team/TeamService'
import HelpTip from '../../shared/ui/HelpTip.vue'
import AppDialog from '../../shared/ui/AppDialog.vue'
import AppIcon from '../../shared/ui/AppIcon.vue'
import {readTextDocument} from './DocumentImport'
import {useLlmConsent} from '../../shared/api/useLlmConsent'
const team=String(useRoute().params.team),base=`/teams/${team}/knowledge`
interface Box{id:string;name:string;department:string;createdBy:string;sharing:'PRIVATE'|'TEAM_SHARED'}
interface CatalogBox{id:string;name:string;department:string;sharing:string;accessible:boolean;owned:boolean}
interface AccessRequest{id:string;boxId:string;boxName:string;requesterId:string;status:string}
interface Document{id:string;boxId:string;title:string;content:string}
interface Agent{id:string;name:string;department:string}
interface Answer{answer:string;provider:string;citations:{sourceId:string;title:string;quote:string}[];tools:{name:string;status:string;sources:number}[]}
const data=ref<{boxes:Box[];documents:Document[];agents:Agent[];catalog:CatalogBox[];accessRequests:AccessRequest[]}>({boxes:[],documents:[],agents:[],catalog:[],accessRequests:[]}),members=ref<Member[]>([]),isOwner=ref(false)
const boxName=ref(''),department=ref(''),selected=ref(''),title=ref(''),content=ref(''),saveApproved=ref(false),agentName=ref(''),assigned=ref<string[]>([]),agentId=ref(''),question=ref(''),queryApproved=ref(false),answer=ref<Answer|null>(null),recipient=ref(''),grants=ref<string[]>([]),busy=ref(false),error=ref('')
const sharingConfirm=ref(false)
const {external,ready,consentText,label:modelLabel,statusError,refresh}=useLlmConsent()
watch(external,()=>queryApproved.value=false)
const ownRequests=computed(()=>data.value.accessRequests.filter(r=>r.requesterId===auth.user?.id))
function isRequested(box:string){return ownRequests.value.some(r=>r.boxId===box&&r.status==='PENDING')}
const current=computed(()=>data.value.boxes.find(b=>b.id===selected.value))
const pending=computed(()=>data.value.accessRequests.filter(r=>r.status==='PENDING'&&data.value.boxes.some(b=>b.id===r.boxId&&b.createdBy===auth.user?.id)))
async function importFile(files:FileList|null){
 if(!files?.length)return;error.value=''
 if(files.length>1){error.value='파일을 한 개씩 넣어 주세요.';return}
 if(title.value.trim()||content.value.trim()){error.value='작성 중인 자료를 먼저 저장하거나 지워 주세요.';return}
 try{const draft=await readTextDocument(files[0]!);title.value=draft.title;content.value=draft.content;saveApproved.value=false}catch(e){error.value=(e as Error).message}
}
function sharing(value:'PRIVATE'|'TEAM_SHARED'){return run(async()=>{await api.request(`${base}/boxes/${selected.value}/sharing`,'PUT',{sharing:value});sharingConfirm.value=false})}
function requestAccess(id:string){return run(()=>api.request(`${base}/boxes/${id}/access-requests`,'POST',{}))}
function decide(id:string,approved:boolean){return run(()=>api.request(`${base}/access-requests/${id}/decision`,'PUT',{approved}))}
watch(selected,()=>saveApproved.value=false)
async function load(){data.value=await api.request(base);members.value=await teamService.members(team);isOwner.value=(await teamService.list()).some(t=>t.id===team&&t.role==='OWNER')}
async function run(action:()=>Promise<unknown>){busy.value=true;error.value='';try{await action();await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function showGrants(){grants.value=[];if(selected.value&&data.value.boxes.some(b=>b.id===selected.value&&b.createdBy===auth.user?.id))grants.value=await api.request<string[]>(`${base}/boxes/${selected.value}/grants`)}
async function ask(){if(!ready.value||!queryApproved.value)return;answer.value=null;await run(async()=>{answer.value=await api.request<Answer>(`${base}/agents/${agentId.value}/ask`,'POST',{question:question.value,approved:true,externalApproved:external.value})})}
const owns=computed(()=>data.value.boxes.some(b=>b.id===selected.value&&b.createdBy===auth.user?.id))
const others=computed(()=>members.value.filter(m=>m.id!==auth.user?.id))
function createBox(){return run(async()=>{await api.request(base+'/boxes','POST',{name:boxName.value,department:department.value});boxName.value=''})}
function createDocument(){return run(async()=>{await api.request(base+'/documents','POST',{boxId:selected.value,title:title.value,content:content.value,approved:saveApproved.value});title.value='';content.value='';saveApproved.value=false})}
function createAgent(){return run(async()=>{await api.request(base+'/agents','POST',{name:agentName.value,department:department.value,boxIds:assigned.value});agentName.value='';assigned.value=[]})}
function grant(allowed:boolean){return run(async()=>{await api.request(`${base}/boxes/${selected.value}/grants`,'PUT',{userId:recipient.value,allowed});await showGrants()})}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section><RouterLink class="back" :to="`/teams/${team}`">팀 회의로 돌아가기</RouterLink><h1>팀 자료함</h1><p>자료를 연결해 두면 회의에서 다시 설명할 일이 줄어들어요. 에이전트는 내 권한과 배정 범위가 모두 허용하는 자료만 참고해요.</p><div class="workspace-navigation"><RouterLink :to="'/teams/'+team"><AppIcon name="note" :size="17"/>회의</RouterLink><span class="selected"><AppIcon name="folder" :size="17"/>자료함</span><RouterLink :to="'/teams/'+team+'/usage'"><AppIcon name="usage" :size="17"/>AI 사용량</RouterLink></div><p v-if="error" role="alert" class="notice error">{{error}}</p><details><summary>팀의 자료함 · 읽기 권한 요청 <HelpTip label="자료함 목록">팀원은 자료함 이름과 부서 분류를 볼 수 있어요. 문서 내용은 읽기 권한이 있어야 볼 수 있어요.</HelpTip></summary><ul class="box-list"><li v-for="box in data.catalog" :key="box.id"><strong>{{box.name}}</strong><small>{{box.department}} · {{box.sharing==='TEAM_SHARED'?'팀 전체 공유':'지정한 사람만'}}</small><button v-if="!box.accessible" class="quiet-button" :disabled="busy||isRequested(box.id)" @click="requestAccess(box.id)">{{isRequested(box.id)?'승인 기다리는 중':'읽기 권한 요청'}}</button><small v-else>읽을 수 있어요</small></li></ul></details>
<details><summary>권한 요청 관리 <span v-if="pending.length">· {{pending.length}}개 대기</span></summary><h3>받은 요청</h3><p v-if="!pending.length" class="muted">처리할 요청이 없어요.</p><article v-for="r in pending" :key="r.id" class="access-request"><p>{{members.find(m=>m.id===r.requesterId)?.name||'팀원'}} · {{r.boxName}}</p><div class="actions"><button :disabled="busy" @click="decide(r.id,true)">읽기 허용</button><button class="secondary" :disabled="busy" @click="decide(r.id,false)">거절</button></div></article><h3>내가 보낸 요청</h3><p v-for="r in ownRequests" :key="r.id">{{r.boxName}} · {{r.status==='PENDING'?'승인 기다리는 중':r.status==='APPROVED'?'허용됨':'거절됨'}}</p></details>
<div class="two-columns"><div><h2>접근 가능한 자료함</h2><p v-if="!data.boxes.length" class="empty">아직 읽을 수 있는 자료가 없어요. 자료함을 만들거나 소유자에게 읽기 권한을 요청해 주세요.</p><label>자료함<select v-model="selected" @change="showGrants().catch(e=>error=e.message)"><option value="">자료함 선택</option><option v-for="box in data.boxes" :key="box.id" :value="box.id">{{box.department}} · {{box.name}}</option></select></label><ul class="task-list"><li v-for="doc in data.documents.filter(d=>d.boxId===selected)" :key="doc.id"><details><summary>{{doc.title}}</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{doc.content}}</pre></details></li></ul><details><summary>자료함 만들기</summary><form @submit.prevent="createBox"><label>자료함 이름<input v-model="boxName" required maxlength="80"></label><label>부서·그룹 이름<input v-model="department" required maxlength="80"></label><button :disabled="busy">자료함 생성</button></form></details><template v-if="owns"><div class="sharing-control"><h3>공유 범위 <HelpTip label="회의 자료 공유">개인 읽기 권한과 회의 공유 권한은 달라요. 팀 전체 공유를 켜야 회의 AI 답변에 사용할 수 있어요.</HelpTip></h3><p class="helper">{{current?.sharing==='TEAM_SHARED'?'팀원 모두가 읽을 수 있고, 연결된 에이전트가 회의에서도 참고해요.':'허용한 사람만 읽을 수 있어요. 회의 AI의 공유 답변에는 쓰지 않아요.'}}</p><button class="secondary" :disabled="busy" @click="current?.sharing==='TEAM_SHARED'?sharing('PRIVATE'):sharingConfirm=true">{{current?.sharing==='TEAM_SHARED'?'지정한 사람만 읽도록 변경':'팀 전체 공유로 변경'}}</button></div><details><summary>자료 등록</summary><form @submit.prevent="createDocument"><label class="drop-zone" @dragover.prevent @drop.prevent="importFile($event.dataTransfer?.files||null)">텍스트 파일을 놓거나 선택해 주세요<input type="file" accept=".txt,.md" @change="importFile(($event.target as HTMLInputElement).files)"><small>.txt · .md / 80KB 이하, 20,000자까지 · 저장 전에는 서버에 보내지 않아요.</small></label><label>제목<input v-model="title" required maxlength="160"></label><label>자료 원문<textarea v-model="content" required maxlength="20000" rows="8"/></label><label class="check"><input v-model="saveApproved" type="checkbox">내용과 공유 범위를 확인했어요. 이 자료함에 저장할게요.</label><button :disabled="busy||!saveApproved">자료 저장</button><button type="button" class="quiet-button" @click="title='';content='';saveApproved=false">입력 지우기</button></form></details><details><summary>팀원 읽기 권한</summary><label>팀원<select v-model="recipient"><option value="">선택</option><option v-for="member in others" :key="member.id" :value="member.id">{{member.name}} · {{grants.includes(member.id)?'허용':'미허용'}}</option></select></label><div class="actions"><button :disabled="busy||!recipient" @click="grant(true)">읽기 허용</button><button class="secondary" :disabled="busy||!recipient" @click="grant(false)">개별 권한 해제</button></div><p class="helper">팀 전체 공유가 켜져 있으면 개별 권한을 해제해도 계속 읽을 수 있어요.</p></details></template></div><div><h2>에이전트에게 확인</h2><p class="helper">여기서는 개인 읽기 권한으로 질문해요. 화면 공유 중에는 비공개 내용이 보이지 않도록 주의해 주세요.</p><form @submit.prevent="ask"><label>에이전트<select v-model="agentId" required><option value="">에이전트 선택</option><option v-for="agent in data.agents" :key="agent.id" :value="agent.id">{{agent.department}} · {{agent.name}}</option></select></label><label>질문<textarea v-model="question" required maxlength="2000" rows="3"/></label><label class="check"><input v-model="queryApproved" type="checkbox">{{consentText}}</label><p v-if="statusError||!ready" class="notice" role="status">{{statusError||modelLabel}} <button type="button" class="quiet-button" @click="queryApproved=false;refresh()">설정 다시 확인</button></p><button :disabled="!ready||busy||!queryApproved">{{busy?'자료를 확인하고 있어요…':'에이전트에게 질문'}}</button></form><div v-if="answer" aria-live="polite"><p class="record-note">{{answer.provider==='deepseek'?'DeepSeek API 사용':answer.provider==='external'?'외부 API 사용':'로컬 모델 사용'}} · 검토용 답변</p><p style="white-space:pre-wrap">{{answer.answer}}</p><details><summary>도구 호출 이력</summary><ul><li v-for="(tool,i) in answer.tools" :key="i">{{tool.name}} · {{tool.status}} · 근거 {{tool.sources}}개</li></ul></details><details v-for="source in answer.citations" :key="source.sourceId"><summary>{{source.title}}</summary><blockquote>{{source.quote}}</blockquote></details></div><details v-if="isOwner"><summary>에이전트 만들기 · 팀 소유자</summary><form @submit.prevent="createAgent"><label>에이전트 이름<input v-model="agentName" required maxlength="80"></label><label>부서 이름<input v-model="department" required maxlength="80"></label><fieldset><legend>읽을 자료함</legend><label v-for="box in data.boxes" :key="box.id" class="check"><input v-model="assigned" type="checkbox" :value="box.id">{{box.name}}</label></fieldset><button :disabled="busy||!assigned.length">에이전트 연결</button><p class="helper">부서 이름은 분류용이에요. 같은 이름이라고 자동으로 자료 권한을 받지는 않아요.</p></form></details></div></div><AppDialog :open="sharingConfirm" title="팀 전체에 공유할까요?" @close="sharingConfirm=false"><p>이 자료함의 모든 문서를 팀원이 읽을 수 있고, 연결된 에이전트가 회의 답변에 사용할 수 있어요.</p><div class="dialog-actions"><button class="secondary" @click="sharingConfirm=false">취소</button><button :disabled="busy" @click="sharing('TEAM_SHARED')">팀 전체 공유</button></div></AppDialog></section></template>
